"""Build inspectable static tables from hash-bound CI reports, not hand-entered results."""
import json,html
from pathlib import Path
root=Path('docs/coach/phase11');read=lambda n:json.loads((root/n).read_text());esc=html.escape
style='''<style>*{box-sizing:border-box}body{margin:0;background:#edf4ee;color:#164b39;font:16px/1.6 system-ui}main{max-width:1180px;margin:auto;padding:24px}h1{font-size:clamp(2rem,5vw,3.5rem);line-height:1.1}h2{line-height:1.25}section{padding:22px;background:white;border:1px solid #ccdbd0;border-radius:16px;margin:20px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}.badge{display:inline-block;background:#ffe2d9;color:#862e1f;padding:8px 15px;border-radius:30px;font-weight:700}a{color:#07583c;text-underline-offset:3px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:10px;border-bottom:1px solid #dce7de}code,pre{white-space:pre-wrap;overflow-wrap:anywhere}small{display:block}.label{text-transform:uppercase;letter-spacing:.12em;font-size:.8rem}summary{cursor:pointer}input{padding:12px;font:inherit;width:100%}@media(max-width:600px){main{padding:14px}section{padding:14px}}</style>'''
def wrap(title,content):return '<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PARISFIT · '+title+'</title>'+style+'</head><body><main>'+content+'</main></body></html>'
rig=read('anatomy-summary.json');ev=read('evidence.json');reports={m:read(m+'_report.json') for m in 'ABC'}
content='<a href="index.html">← Phase11</a><h1>111 os, sans longueur inventée.</h1><p>Inventaire métrique importé :31os source et80os cible. Z-up dans cet inventaire ; rapports cinématiques Y-up. Longueur graphique Blender ≠ distance entre pivots anatomiques. Matrices relatives = orientation de repos et translation dans le repère parent ; axes mondiaux explicités. Ce sont les axes du rig, pas des axes anatomiques certifiés.</p><p><a href="anatomy-summary.json">Données complètes de ce tableau</a> · <a href="ANATOMY.md">Interprétation des incompatibilités</a></p><input id="filter" placeholder="Filtrer les os : Spine, Hand, Calf…" aria-label="Filtrer les os">'
for side,label in [('source','Source CMU'),('target','Cible Rocketbox')]:
 content+='<section><h2>'+label+'</h2><p>Échelle objet : '+esc(str(rig[side]['objectScale']))+'</p>'
 for b in rig[side]['bones']:
  content+='<details data-bone="'+esc(b['name'].lower())+'"><summary><strong>'+esc(b['name'])+'</strong> ← '+esc(str(b['parent']))+'</summary><pre>'+esc(json.dumps(b,indent=2,ensure_ascii=False))+'</pre></details>'
 content+='</section>'
content+='<section><h2>22 correspondances</h2><div class="scroll"><table><tr><th>Cible / source</th><th>Classe</th><th>Source (mm)</th><th>Cible (mm)</th><th>Ratio cible/source</th></tr>'
for m in rig['mapping']:
 fmt=lambda v:'indisponible' if v is None else f'{v:.3f}'
 content+='<tr><td>'+esc(m['target'])+'<small>'+esc(m['source'])+'</small></td><td>'+esc(m['class'])+'<small>'+esc(m['reason'])+'</small></td><td>'+fmt(None if m['sourceSegmentM'] is None else m['sourceSegmentM']*1000)+'</td><td>'+fmt(None if m['targetSegmentM'] is None else m['targetSegmentM']*1000)+'</td><td>'+fmt(m['ratio'])+'</td></tr>'
content+='</table></div><h3>Os cible non pilotés directement</h3><p>'+esc(', '.join(rig['unmappedTarget']))+'</p><h3>Os source non associés</h3><p>'+esc(', '.join(rig['unusedSource']))+'</p><p>Non piloté directement : conserve la rotation locale de repos et hérite du parent, pas une capture de doigts ou de visage.</p></section><script>document.getElementById("filter").oninput=e=>document.querySelectorAll("[data-bone]").forEach(d=>d.hidden=!d.dataset.bone.includes(e.target.value.toLowerCase()));</script>'
(root/'anatomy.html').write_text(wrap('Cartographie anatomique',content))
metrics=[('Pénétration peau (mm)','maxSurfacePenetrationM',1000),('Gap pied maximum (mm)','maxFootGapM',1000),('Dérive contacts candidats (mm)','maxCandidateStanceDriftM',1000),('Accélération max (m/s²)','maxJointAccelerationMS2',1),('Vitesse max (m/s)','maxJointSpeedMS',1),('Pas articulaire max (mm)','maxJointStepM',1000),('Rotation max (°/frame)','maxRotationStepDeg',1),('Accélération bassin (m/s²)','maxPelvisAccelerationMS2',1),('Écart entrée/sortie (mm)','entryExitMaxJointGapM',1000)]
rows=''.join('<tr><th>'+label+'</th>'+''.join('<td>'+f'{reports[m]["observedModelGeometry"][key]*factor:.3f}'+'</td>' for m in 'ABC')+'</tr>' for label,key,factor in metrics)
rows+='<tr><th>RMS pivots source normalisés (mm), proxy</th>'+''.join('<td>'+f'{reports[m]["extra"]["sourceTrajectoryProxy"]["rmsM"]*1000:.3f}'+'</td>' for m in 'ABC')+'</tr>'
run='https://github.com/aydiarra-star/PARISFIT/actions/runs/'+ev['run']
content='''<a href="../phase10/index.html">← Phase10 · preuves conservées</a><header><p class="label">PARISFIT / Phase11 / Diagnostic anatomique</p><h1>Comprendre le corps.<br>Ne pas masquer le défaut.</h1><p class="badge">Aucune animation admissible</p><p>Trois méthodes comparées sur la même source CMU. Rocketbox et les huit exercices conservés. Aucun candidat d’intégration, aucune capture PARISFIT fabriquée.</p></header><section><h2>Ce que la comparaison établit</h2><p>B réduit fortement l’erreur de sol et redresse le tronc, mais reste hors critères. C réduit la dérive sur les contacts estimés, tout en amplifiant fortement les accélérations. <strong>Ni une silhouette plus plausible, ni un pied plus immobile ne prouvent la fidélité humaine.</strong></p><div class="scroll"><table><thead><tr><th>Mesure sur145poses</th><th>A · direct</th><th>B · morphologie</th><th>C · cinématique</th></tr></thead><tbody>'''+rows+'''</tbody></table></div><p>Les fenêtres d’appui diffèrent : ces dérives ne sont pas un classement sur contacts mesurés identiques. COM, contacts et collisions restent estimés ; torsions anatomiques et collisions exhaustives NON TESTÉES.</p></section><div class="grid"><section><h2>Cartographie des rigs</h2><p>31os CMU,80os Rocketbox : hiérarchie, longueurs, axes, repos, échelles et correspondances impossibles explicités.</p><p><a href="anatomy.html">Explorer les111os</a> · <a href="ANATOMY.md">Diagnostic anatomique</a></p></section><section><h2>Méthodes et preuves</h2><p><a href="METHODS.md">Protocole et reproduction</a><br><a href="REPORT.md">Résultats et défauts non résolus</a><br><a href="A_report.json">Rapport A</a> · <a href="B_report.json">B</a> · <a href="C_report.json">C</a><br><a href="three-report.json">Contrôle Three.js</a> · <a href="evidence.json">Provenance et hashes</a></p></section></div><section><h2>21 vidéos de diagnostic</h2><p>Pour chaque méthode : face, profil, trois-quarts, ralenti, appuis, squelette et superposition source/cible. Les vues squelettiques sont des outils d’analyse, pas un remplacement du modèle humain.</p><p><a href="'''+run+'''">Télécharger l’artifact phase11-anatomical-diagnostics depuis la CI</a></p><p>Extraire l’archive puis ouvrir son <code>index.html</code>. Les3GLB sont exclusivement des diagnostics refusés. <a href="video-report.json">Inventaire des films et hashes</a>.</p><p>Le téléchargement des artifacts reste bloqué ici : aucune revue visuelle déclarée. Les8films phase10 n’ont pas pu être examinés. Tests de décodage ≠ avis visuel.</p></section><div class="grid"><section><h2>Revue professionnelle</h2><p class="badge">En attente de validation humaine</p><p><a href="PROFESSIONAL-REVIEW.md">Grille de revue non remplie</a></p><p>Genoux, pieds, bassin, tronc, amplitude, descente, remontée et réserves selon variante. Aucun avis sportif inventé.</p></section><section><h2>Capture PARISFIT</h2><p><a href="CAPTURE-STATUS.md">Provenance et protocole maintenu</a></p><p>En attente d’un enregistrement adulte autorisé. Signatures et données privées hors GitHub.</p></section></div><section><h2>Décision</h2><p>REFUSÉ pour A/B/C. Pas de reconstruction candidate avec les critères fondamentaux en échec. PR11 reste en brouillon, sans achat, activation, fusion ni déploiement.</p></section>'''
(root/'index.html').write_text(wrap('Diagnostic anatomique',content))
